INSERT INTO public.approved_answers (id, topic, question_variants, answer, version, status)
VALUES
  ('84d0919a-f564-5362-8557-c09f4294532a'::uuid, 'services_overview', ARRAY['What do your AI services do?', 'What can Pristaine help my business with?', 'Which AI services does Pristaine offer?', 'What does Pristaine build?']::text[], 'Pristaine focuses on four areas: conversational AI and chatbots for website and messaging conversations; Voice AI phone agents that can answer and qualify callers and support call booking; custom AI automations and integrations around existing workflows; and AI consultation to help identify a practical place to start. The best fit depends on your goals and constraints.', '1.0.0-draft', 'draft'),
  ('2e49fcd9-6c61-55d5-9b41-047e7b5155e1'::uuid, 'conversational_ai', ARRAY['What is conversational AI?', 'What is an AI chatbot?', 'Can Pristaine build a website chatbot?', 'Do you build chatbots for websites and messaging?']::text[], 'Conversational AI lets people ask questions and receive responses through a chat interface or messaging channel. Pristaine describes its chatbot service as helping businesses answer customer questions across websites and messaging channels, with guardrails and testing included in the intended approach. The exact behavior and integrations should be agreed for each project.', '1.0.0-draft', 'draft'),
  ('998f4188-6bf7-52b9-aff7-3e72396f41fa'::uuid, 'voice_ai', ARRAY['What is Voice AI?', 'Do you build AI phone agents?', 'Can AI answer business phone calls?', 'Can a voice agent qualify callers and book calls?']::text[], 'Voice AI uses AI to have spoken conversations, often over phone calls. Pristaine describes its Voice AI service as AI phone agents that can answer callers, qualify inquiries and support call booking. The exact call flow, integrations and situations requiring a human should be agreed and tested for each project.', '1.0.0-draft', 'draft'),
  ('0e094bf4-5a82-58b1-a98f-fc564d9a5543'::uuid, 'custom_ai_solutions', ARRAY['What are Pristaine AI Solutions?', 'Do you build custom AI automations?', 'Can you automate an existing workflow?', 'What does custom AI automation mean?']::text[], 'Pristaine’s AI Solutions service focuses on custom automations and integrations built around a business’s workflows and existing tools. A suitable approach depends on the workflow, available systems and APIs, permissions, data quality and technical constraints. A specific integration should be confirmed after reviewing those details.', '1.0.0-draft', 'draft'),
  ('db85756f-7fae-56f1-b0d0-4aa81dcebf03'::uuid, 'ai_consultation', ARRAY['What is AI consultation?', 'Can you help us decide where to start with AI?', 'How do we find the right first AI project?', 'What happens in an AI consultation?']::text[], 'AI consultation helps a business explore where AI may be useful first and identify a practical starting point. A useful discussion covers the business goal, current workflow, tools involved, constraints and how success could be measured. The consultation does not guarantee a particular result.', '1.0.0-draft', 'draft'),
  ('7bf670f3-2a0d-59fa-845b-022faa3cd902'::uuid, 'target_audience', ARRAY['Who does Pristaine work with?', 'Which businesses are you focused on?', 'Do you work with small and mid-sized businesses?', 'Does Pristaine serve businesses in the US and Canada?']::text[], 'Pristaine’s stated audience is small and mid-sized businesses in the United States and Canada, especially businesses handling customer calls, chats and inquiries. Whether a particular project is a good fit depends on the problem to solve, the available systems and the project’s requirements.', '1.0.0-draft', 'draft'),
  ('79601255-7fb6-5e0b-9407-11ec03bfb204'::uuid, 'existing_tools', ARRAY['Which tools and systems can your AI connect to?', 'Can your solutions work with our existing software?', 'Will we need to replace our current tools?']::text[], 'Pristaine’s AI Solutions service is intended to work around existing workflows and tools where practical. Whether a specific connection is possible depends on the systems involved, API availability, permissions, data access and technical constraints. Those details need to be reviewed before a particular integration is confirmed.', '1.0.0-draft', 'draft'),
  ('7bf49798-97a0-5bc3-938b-c63bbc676b57'::uuid, 'getting_started', ARRAY['How do we get started with Pristaine?', 'What should I prepare before contacting you?', 'What do you need to start an AI project?']::text[], 'Start with the business goal, the problem or workflow you want to improve, the tools currently involved and any important constraints. It also helps to describe what a useful outcome would look like. You can use the Book a Consultation page or the website’s contact form to discuss next steps.', '1.0.0-draft', 'draft'),
  ('29053dbf-a424-50d2-b8a7-015d7487e416'::uuid, 'project_timeline', ARRAY['How long does an AI project take?', 'When can my chatbot be ready?', 'How soon can an AI solution launch?']::text[], 'There is no single timeline for every AI project. Timing depends on the scope, integrations, data availability, access and permissions, testing needs and the number of workflows involved. Requirements should be clarified before a project timeline is proposed; this assistant cannot confirm a delivery date.', '1.0.0-draft', 'draft'),
  ('e6f04d6e-e826-58b6-890b-e00b8a06bd24'::uuid, 'testing_ai', ARRAY['How do you test an AI assistant?', 'What testing happens before launch?', 'How do you check whether an AI chatbot works properly?']::text[], 'A test plan can cover expected questions, edge cases, privacy and security checks, unsupported requests, fallback behavior and human review. The right tests depend on the assistant’s purpose and the risks if it gives an incorrect answer. A specific project’s test status should be confirmed directly rather than assumed.', '1.0.0-draft', 'draft'),
  ('3d87e12a-19ff-58e4-9f90-69dbd9e88adb'::uuid, 'unknown_answer_handoff', ARRAY['What happens when the AI cannot answer?', 'What if the chatbot is unsure?', 'Can the AI hand off to a person?']::text[], 'An AI assistant should be clear when it cannot answer reliably and provide an agreed next step, such as contacting the team or requesting human help. This website offers a Book a Consultation option and a contact form. Do not assume that an immediate live transfer is available unless the project explicitly implements one.', '1.0.0-draft', 'draft'),
  ('1469599e-279a-5001-a1d0-6e381b89159b'::uuid, 'measuring_success', ARRAY['How do we measure whether an AI project is successful?', 'How do we know if the AI project is useful?', 'What should we measure for an AI assistant?']::text[], 'Define the problem and a measurable objective before implementation. Depending on the use case, a team might review answer quality, successful task completion, appropriate human handoffs, response time or error rates. The measures should fit the workflow; results should be evaluated rather than promised in advance.', '1.0.0-draft', 'draft'),
  ('f829ceaf-fa80-5807-80b4-4735e198326f'::uuid, 'project_requirements', ARRAY['What information is useful for an AI consultation?', 'What should I tell you about my workflow?', 'What do you need to understand our business process?']::text[], 'Useful starting information includes the business goal, the current process, the systems involved, repetitive tasks or common customer inquiries, access or permission limits, data sensitivity and the outcome you want to measure. Do not send passwords, payment details, government IDs or other sensitive personal information through this chat.', '1.0.0-draft', 'draft'),
  ('50ecfde0-3830-5e6f-b554-e0ae3324777e'::uuid, 'data_privacy', ARRAY['How do you handle data and privacy?', 'What happens to our data during an AI project?', 'How is customer information handled?']::text[], 'Data handling should be agreed before implementation, including what is collected, how it is processed, who can access it and how long it is retained. The appropriate safeguards depend on the project and the data involved. Review the current Privacy Policy and confirm project-specific requirements before sharing customer information.', '1.0.0-draft', 'draft'),
  ('706d90a2-bf5f-57a0-8f8d-7790b19e27f6'::uuid, 'sensitive_information', ARRAY['Can I share sensitive details in this chat?', 'Should I provide my password or payment details?', 'What information should I not type into the AI assistant?']::text[], 'Please do not share government identification numbers, passport or driver’s licence details, payment or account information, passwords, PINs, security answers, biometric data or health information in this chat. Describe your question without secret or identifying details, or contact Pristaine through the website’s contact form.', '1.0.0-draft', 'draft'),
  ('5897e0db-da28-5f17-83fb-b7ed5f8b2a27'::uuid, 'chat_storage_notice', ARRAY['Is this chat saved?', 'Does the assistant store conversations?', 'Is this an AI assistant that processes my message?']::text[], 'Pristaine’s documented design states that chat conversations are saved and processed by an AI provider. Before sending a message, read the notice shown beside the chat and review the current Privacy Policy for the applicable details. Please do not enter sensitive information. If the notice or policy does not answer your question, use the website’s contact form.', '1.0.0-draft', 'draft'),
  ('250b6ca0-394b-5ceb-8b5e-df3198cd7d70'::uuid, 'pricing', ARRAY['How much does an AI project cost?', 'What are your chatbot prices?', 'Can you share your pricing?']::text[], 'I do not have an approved price list to quote. Project cost depends on the requirements, scope, integrations and testing needs. Pristaine can discuss your situation through a consultation or the website’s contact form, but this assistant cannot confirm a project price or estimate.', '1.0.0-draft', 'draft'),
  ('6fc69c0b-ac46-5102-a274-e5df9b2ee43a'::uuid, 'guaranteed_results', ARRAY['Can you guarantee results?', 'Do you guarantee return on investment?', 'Can you promise cost savings?']::text[], 'No specific outcome or return on investment should be promised before the use case is assessed and measured. A project should begin with a clear problem, agreed success measures and appropriate testing. Actual results depend on the workflow, data, implementation and how the solution is used.', '1.0.0-draft', 'draft'),
  ('39c2db6a-8689-573f-8dbe-2eff848788bb'::uuid, 'certifications_and_compliance', ARRAY['What certifications do you have?', 'Are you certified or compliant with a specific standard?', 'Are you SOC 2, PIPEDA or GDPR compliant?']::text[], 'I do not have approved information confirming specific certifications or compliance claims, so I will not assert them. For a current, verified answer about a particular standard, ask Pristaine directly through the website’s contact form. Do not treat this response as a legal or compliance determination.', '1.0.0-draft', 'draft'),
  ('41f8dcdc-f655-5eb7-8a22-a432f1245c57'::uuid, 'professional_advice_limits', ARRAY['Can you give legal advice?', 'Can you give financial advice?', 'Can I use this assistant for medical advice?']::text[], 'No. This assistant provides general information about AI and Pristaine’s services, not legal, medical or financial advice tailored to your situation. For decisions in those areas, consult an appropriately qualified professional.', '1.0.0-draft', 'draft'),
  ('4864d09d-3789-552f-bfa6-9a68486a4fa5'::uuid, 'assistant_identity', ARRAY['Are you a real person?', 'Am I talking to a human?', 'Who am I chatting with?']::text[], 'I am Pristaine’s AI assistant, not a person. I can share general information about AI and Pristaine’s services, but I cannot independently confirm project-specific pricing, delivery dates, commitments or outcomes. You can request human follow-up through the Book a Consultation page or the website’s contact form.', '1.0.0-draft', 'draft'),
  ('ae97f526-821a-53c2-b1ff-96eae4ff25ad'::uuid, 'ai_automation_definition', ARRAY['What is AI automation?', 'How can AI automate a business workflow?', 'What does business process automation with AI mean?']::text[], 'AI automation uses AI to help perform or support parts of a workflow—for example, interpreting incoming requests, classifying information or drafting a response. Good designs define what the AI may do, how results are checked, what happens when it is uncertain and when a person must review or take over.', '1.0.0-draft', 'draft'),
  ('b4239fa2-30ed-582e-b917-c36772b20f7a'::uuid, 'chatbot_vs_voice_agent', ARRAY['What is the difference between a chatbot and a voice agent?', 'How is Voice AI different from a website chatbot?', 'When should I use a chatbot versus Voice AI?']::text[], 'A chatbot usually interacts through typed messages on a website or messaging channel. A voice agent interacts through spoken conversation, often by phone. The best choice depends on how customers prefer to communicate, the task to complete, the systems involved and the risks of an incorrect response.', '1.0.0-draft', 'draft'),
  ('29c2b838-0cbe-5d46-bf26-3f19650fdac6'::uuid, 'ai_accuracy', ARRAY['Can AI make mistakes?', 'Is AI always accurate?', 'Can I trust every AI answer?']::text[], 'AI can misunderstand a question or produce an incorrect or incomplete answer. Important uses need representative testing, clear limits, checks on outputs and a safe path when the system is uncertain. High-impact decisions should not rely only on an unverified AI response.', '1.0.0-draft', 'draft'),
  ('ae994b5c-40c7-5cac-b045-e9ebc00c4adb'::uuid, 'ai_and_jobs', ARRAY['Will AI replace my employees?', 'Does automation mean replacing staff?', 'Should AI replace my team?']::text[], 'AI does not automatically mean replacing an employee or an entire role. It may support specific tasks or automate part of a process, while people continue to handle judgment, exceptions and sensitive decisions. The right approach depends on the workflow, risks, quality requirements and the role of human oversight.', '1.0.0-draft', 'draft'),
  ('41a5194f-2267-5d4b-8e46-63565709b6f1'::uuid, 'ai_guardrails_definition', ARRAY['What are AI guardrails?', 'How can AI be kept within its intended limits?', 'What does safer AI behavior mean?']::text[], 'AI guardrails are controls that limit how an AI system is used and how it responds. They can include input checks, approved knowledge, limits on the tasks it may perform, output checks, privacy protections, monitoring and a fallback when a check fails. The controls should match the system’s purpose and risks.', '1.0.0-draft', 'draft'),
  ('17e0cb5e-3b8f-5926-9068-2f555ec5c29e'::uuid, 'ai_suitability', ARRAY['Is AI right for every business?', 'Should every task be automated?', 'How do I know if a task is suitable for AI?']::text[], 'Not every task is a good fit for AI. Start with a clear, repeatable problem; consider whether suitable data and system access are available; assess the impact of mistakes; and decide how outputs will be checked. A small, measurable and lower-risk use case can be a more useful starting point than automating everything at once.', '1.0.0-draft', 'draft'),
  ('2c7d92c3-dc7d-54c8-a73f-46873944d281'::uuid, 'customer_data_and_ai', ARRAY['Can I send customer data to an AI tool?', 'Is it safe to put customer information into AI?', 'What should a business check before using AI with personal data?']::text[], 'Before using personal or confidential data with an AI system, review the purpose, consent and legal requirements, provider terms, access controls, retention, data location and what information is truly necessary. Do not paste sensitive or identifying customer details into this chat. Specific requirements should be reviewed for the actual project and jurisdiction.', '1.0.0-draft', 'draft')
